export enum ReadingState { QUEUED, ACTIVE, FINISHED }
export type ReadingItem = {
  id: number;
  title: string;
  summary: string;
  state: ReadingState;
  targetDate?: string;
};
export type LengthFeedback = {
  titleCount: number;
  summaryCount: number;
  titleAtLimit: boolean;
  summaryAtLimit: boolean;
};
export class ReadingPlan {
  static readonly TITLE_LIMIT: number;
  static readonly SUMMARY_LIMIT: number;
  measure(title: string, summary: string): LengthFeedback;
  add(title: string, summary: string, state: ReadingState, targetDate?: string): ReadingItem;
  getAll(): ReadingItem[];
}
```

Set the limits to 40 and 240 Unicode code points. `measure` accepts empty strings, counts Unicode code points rather than UTF-16 code units, and sets each `AtLimit` flag when its count is greater than or equal to the corresponding limit. Non-string values throw `TypeError` at runtime.

`add` requires a title containing at least one non-whitespace character, permits an empty summary, and rejects either field when its count exceeds its limit. The state must be one of the three enum values. If supplied, `targetDate` must exactly match `YYYY-MM-DD`; calendar validity is not required. Invalid input throws `TypeError` without consuming an ID. Preserve text exactly. IDs begin at 1 and increase without reuse. `getAll` preserves insertion order. Returned objects and arrays must not alias internal state.

