import { ReadingPlan, ReadingState } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function captures(fn: () => void): unknown {
  try { fn(); } catch (error) { return error; }
  return undefined;
}

assert(ReadingPlan.TITLE_LIMIT === 40, 'title limit');
assert(ReadingPlan.SUMMARY_LIMIT === 240, 'summary limit');
const plan = new ReadingPlan();
deepEqual(plan.measure('', ''), { titleCount: 0, summaryCount: 0, titleAtLimit: false, summaryAtLimit: false }, 'empty strings measured');
deepEqual(plan.measure('😀'.repeat(40), 'x'.repeat(240)), { titleCount: 40, summaryCount: 240, titleAtLimit: true, summaryAtLimit: true }, 'counts Unicode code points and marks exact limits');
deepEqual(plan.measure('a'.repeat(41), '😀'.repeat(241)), { titleCount: 41, summaryCount: 241, titleAtLimit: true, summaryAtLimit: true }, 'over-limit measurements allowed');
assert(captures(() => plan.measure(3 as unknown as string, '')) instanceof TypeError, 'measure rejects non-string title');
assert(captures(() => plan.measure('', null as unknown as string)) instanceof TypeError, 'measure rejects non-string summary');

const first = plan.add('  Exact text  ', '', ReadingState.QUEUED);
deepEqual(first, { id: 1, title: '  Exact text  ', summary: '', state: ReadingState.QUEUED }, 'add preserves text and omits target date');
const second = plan.add('😀'.repeat(40), 's'.repeat(240), ReadingState.ACTIVE, '2026-99-99');
assert(second.id === 2 && second.targetDate === '2026-99-99', 'limits are inclusive and calendar validity is not required');
const third = plan.add('Done', 'Summary', ReadingState.FINISHED, '0000-00-00');
assert(third.id === 3, 'all enum states accepted');
first.title = 'Mutated';
const listed = plan.getAll();
listed[0].title = 'Changed';
listed.pop();
assert(plan.getAll().length === 3 && plan.getAll()[0].title === '  Exact text  ', 'outputs are defensive');

const invalidAdds: Array<() => void> = [
  () => plan.add('   \n\t', '', ReadingState.QUEUED),
  () => plan.add('x'.repeat(41), '', ReadingState.QUEUED),
  () => plan.add('X', 's'.repeat(241), ReadingState.QUEUED),
  () => plan.add(3 as unknown as string, '', ReadingState.QUEUED),
  () => plan.add('X', null as unknown as string, ReadingState.QUEUED),
  () => plan.add('X', '', 3 as ReadingState),
  () => plan.add('X', '', 'queued' as unknown as ReadingState),
  () => plan.add('X', '', ReadingState.QUEUED, '2026-1-01'),
  () => plan.add('X', '', ReadingState.QUEUED, '2026-01-01x'),
  () => plan.add('X', '', ReadingState.QUEUED, 20260101 as unknown as string)
];
for (const operation of invalidAdds) assert(captures(operation) instanceof TypeError, 'invalid add rejected');
assert(plan.add('After failures', '', ReadingState.QUEUED).id === 4, 'failed additions do not consume ids');

